import zlib from 'node:zlib'
import { promisify } from 'node:util'

const deflate = promisify(zlib.deflateRaw)
// Classic (non-ZIP64) archives: account exports are bounded by quotas far below 4 GiB.
const limit = 0xffffffff, maxEntries = 0xffff
const dosTime = date => {
  const d = new Date(date)
  return { time: (d.getUTCHours() << 11) | (d.getUTCMinutes() << 5) | Math.floor(d.getUTCSeconds() / 2), date: ((Math.max(d.getUTCFullYear(), 1980) - 1980) << 9) | ((d.getUTCMonth() + 1) << 5) | d.getUTCDate() }
}
// Entry names are generated by the exporter; still reject anything that could escape on extraction.
export function safeEntryName(name) {
  if (typeof name !== 'string' || !name || name.length > 512 || name.startsWith('/') || name.includes('\\') || name.split('/').some(part => !part || part === '.' || part === '..') || /[\u0000-\u001f\u007f]/.test(name)) throw Error('Invalid archive entry name')
  return name
}

// Streams entries one at a time; `write` must honor backpressure (resolve when drained).
export function createZipWriter(write) {
  const central = []
  let offset = 0, closed = false
  const emit = async buffer => { offset += buffer.length; if (offset > limit) throw Error('Archive too large'); await write(buffer) }
  return {
    async add(name, content, modified = new Date()) {
      if (closed) throw Error('Archive closed')
      if (central.length >= maxEntries) throw Error('Too many archive entries')
      const file = Buffer.from(safeEntryName(name), 'utf8'), data = Buffer.isBuffer(content) ? content : Buffer.from(String(content), 'utf8')
      const compressed = await deflate(data, { level: 6 }), crc = zlib.crc32(data), { time, date } = dosTime(modified)
      const header = Buffer.alloc(30)
      header.writeUInt32LE(0x04034b50, 0); header.writeUInt16LE(20, 4); header.writeUInt16LE(0x0800, 6); header.writeUInt16LE(8, 8)
      header.writeUInt16LE(time, 10); header.writeUInt16LE(date, 12); header.writeUInt32LE(crc, 14)
      header.writeUInt32LE(compressed.length, 18); header.writeUInt32LE(data.length, 22); header.writeUInt16LE(file.length, 26); header.writeUInt16LE(0, 28)
      central.push({ file, crc, compressed: compressed.length, size: data.length, time, date, offset })
      await emit(Buffer.concat([header, file])); await emit(compressed)
    },
    async close() {
      if (closed) return
      closed = true
      const start = offset
      for (const entry of central) {
        const record = Buffer.alloc(46)
        record.writeUInt32LE(0x02014b50, 0); record.writeUInt16LE(0x0314, 4); record.writeUInt16LE(20, 6); record.writeUInt16LE(0x0800, 8); record.writeUInt16LE(8, 10)
        record.writeUInt16LE(entry.time, 12); record.writeUInt16LE(entry.date, 14); record.writeUInt32LE(entry.crc, 16)
        record.writeUInt32LE(entry.compressed, 20); record.writeUInt32LE(entry.size, 24); record.writeUInt16LE(entry.file.length, 28)
        record.writeUInt32LE((0o100644 << 16) >>> 0, 38); record.writeUInt32LE(entry.offset, 42)
        await emit(Buffer.concat([record, entry.file]))
      }
      const end = Buffer.alloc(22)
      end.writeUInt32LE(0x06054b50, 0); end.writeUInt16LE(central.length, 8); end.writeUInt16LE(central.length, 10)
      end.writeUInt32LE(offset - start, 12); end.writeUInt32LE(start, 16)
      await emit(end)
    },
  }
}
